import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { MediaStorage } from '@/application/media';

/** Keys are generated by the CMS; anything else is refused before touching the file system. */
export const STORAGE_KEY_PATTERN = /^tnt_[0-9a-f]{32}\/site_[0-9a-f]{32}\/med_[0-9a-f]{32}\.(jpg|png|webp|gif|avif|svg)$/;

function assertKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) throw new Error('Invalid storage key');
}

/** Development storage: files under a local folder, served by the CMS at /media/<key>. */
export function createLocalMediaStorage({ dir, baseUrl }: Readonly<{ dir: string; baseUrl: string }>): MediaStorage {
  const fileOf = (key: string) => {
    assertKey(key);
    return path.join(dir, ...key.split('/'));
  };

  return {
    async put(key, bytes) {
      const file = fileOf(key);
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, bytes);
    },
    async delete(key) {
      await rm(fileOf(key), { force: true });
    },
    publicUrl: (key) => `${baseUrl.replace(/\/+$/, '')}/media/${key}`,
    async read(key) {
      if (!STORAGE_KEY_PATTERN.test(key)) return null;
      try {
        return new Uint8Array(await readFile(fileOf(key)));
      } catch {
        return null;
      }
    },
  };
}
